def _kingdomhearts2worldgen_hb_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Membership Card', player, Amount)


def _kingdomhearts2worldgen_ht_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Bone Fist', player, Amount)


def _kingdomhearts2worldgen_hundred_acre_unlocked(state: "CollectionState", player: int, amount = None) -> bool:
    return state.has('Torn Page', player, amount)


def _kingdomhearts2worldgen_kh2_can_reach(state: "CollectionState", player: int, loc = None) -> bool:
    return state.can_reach(state.multiworld.get_location(loc, player), 'location', player)


def _kingdomhearts2worldgen_kh2_can_reach_any(state: "CollectionState", player: int, loc_set = None) -> bool:
    return True


def _kingdomhearts2worldgen_kh2_dict_count(state: "CollectionState", player: int, item_name_to_count = None) -> bool:
    return True


def _kingdomhearts2worldgen_kh2_dict_one_count(state: "CollectionState", player: int, item_name_to_count = None) -> int:
    return sum(1 for [item_name, item_amount] in item_name_to_count.items() if (state.count(item_name, player) >= item_amount))


def _kingdomhearts2worldgen_kh2_has_all(state: "CollectionState", player: int, items = None) -> bool:
    return state.has_all((), player)


def _kingdomhearts2worldgen_kh2_has_any(state: "CollectionState", player: int, items = None) -> bool:
    return state.has_any((), player)


def _kingdomhearts2worldgen_kh2_list_any_sum(state: "CollectionState", player: int, list_of_item_name_list = None) -> int:
    return sum(1 for item_list in list_of_item_name_list if state.has_any((), player))


def _kingdomhearts2worldgen_kh2_list_count_sum(state: "CollectionState", player: int, item_name_set = None) -> int:
    return sum(state.count(item_name, player) for item_name in item_name_set)


def _kingdomhearts2worldgen_level_locking_unlock(state: "CollectionState", player: int, amount = None) -> bool:
    return (True if ('false') and (state.has('Promise Charm', player)) else (amount <= sum(state.count(item_name, player) for item_name in ['Disney Castle Key', 'Battlefields of War', 'Sword of the Ancestor', "Beast's Claw", 'Bone Fist', 'Proud Fang', 'Skill and Crossbones', 'Scimitar', 'Membership Card', 'Ice Cream', 'Way to the Dawn', 'Identity Disk', 'Ice Cream', 'Namine Sketches'])))


def _kingdomhearts2worldgen_lod_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Sword of the Ancestor', player, Amount)


def _kingdomhearts2worldgen_oc_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Battlefields of War', player, Amount)


def _kingdomhearts2worldgen_pl_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Proud Fang', player, Amount)


def _kingdomhearts2worldgen_pr_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Skill and Crossbones', player, Amount)


def _kingdomhearts2worldgen_sp_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Identity Disk', player, Amount)


def _kingdomhearts2worldgen_stt_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Namine Sketches', player, Amount)


def _kingdomhearts2worldgen_tt_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Ice Cream', player, Amount)


def _kingdomhearts2worldgen_twtnw_unlocked(state: "CollectionState", player: int, Amount = None) -> bool:
    return state.has('Way to the Dawn', player, Amount)


